//! Explicit enriched grid and averaged-point snapshot; does not establish runtime identity.
use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_gradient_v1::{evaluate,GradientLane},creature_generated_skin_kernel_v1::Lane,native_sse::Policy};
fn word(b:&[u8],p:usize)->u32{u32::from_le_bytes(b[p..p+4].try_into().unwrap())}
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),3);let b=fs::read(&a[1]).unwrap();let points=fs::read(&a[2]).unwrap();assert!(b.len()>=208);assert_eq!(points.len(),528);let val=|i:usize|f32::from_bits(word(&b,i*4));let origin=[val(9),val(10),val(11)];let scale=[val(12),val(13),val(14)];let threshold=val(8);let mut off=208;let mut owned:Vec<Vec<[GradientLane;4]>>=vec![Vec::new();512];for cell in &mut owned{let n=word(&b,off) as usize;off+=4;assert!(n<=16&&off+n*128<=b.len());for _ in 0..n{let f=|field:usize,lane:usize|f32::from_bits(word(&b,off+field*16+lane*4));let r=std::array::from_fn(|lane|GradientLane{lane:Lane{center:[f(0,lane),f(1,lane),f(2,lane)],cutoff:f(3,lane),scale:f(4,lane),coefficient:f(5,lane),key:word(&b,off+112+lane*4)},derivative:f(6,lane)});cell.push(r);off+=128;}}assert_eq!(off,b.len());let cells:[Option<&[[GradientLane;4]]>;512]=std::array::from_fn(|i|if owned[i].is_empty(){None}else{Some(owned[i].as_slice())});let mut out=Vec::new();for b in points.chunks_exact(12){let p=[f32::from_bits(word(b,0)),f32::from_bits(word(b,4)),f32::from_bits(word(b,8))];let r=evaluate(p,origin,scale,threshold,&cells,Policy::Mxcsr1f80).unwrap();for v in [u32::from(r.usable),r.gradient[0].to_bits(),r.gradient[1].to_bits(),r.gradient[2].to_bits()]{out.extend(v.to_le_bytes());}}io::stdout().write_all(&out).unwrap();}
